"""Original pleural-fluid interpretation and pleural-infection questions."""
from qbank_authoring import question,ref,finalize
PL=ref('BTS: Pleural Disease Guideline, 2023','https://thorax.bmj.com/content/early/2023/08/08/thorax-2023-220304')
PR=ref('BTS: Clinical Statement on Pleural Procedures, 2023','https://thorax.bmj.com/content/78/Suppl_3/s43')
MI=ref('MIST2: Intrapleural tPA and DNase in Pleural Infection','https://www.nejm.org/doi/full/10.1056/NEJMoa1012740')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Serum protein is 6.0 g/dL and pleural protein is 3.6 g/dL. Which interpretation of this component of Light criteria is correct?', 'The protein ratio is 0.60 and meets an exudative criterion',[
 ('The ratio is 0.40 and establishes a transudate','The ratio is pleural divided by serum: 3.6/6.0.'),('All three Light criteria must be positive to call an exudate','Any one positive criterion is sufficient.'),('Protein alone identifies the cause as malignancy','Classification does not establish etiology.')],
 'Apply the ratios before naming the cause', '**A pleural-to-serum protein ratio greater than 0.5 is one exudative criterion.**',['Other criteria concern the LDH ratio and absolute pleural LDH.','Any one positive criterion classifies the fluid as exudative.'], '**Then investigate the clinical differential.**',['Infection, malignancy and inflammatory disease are possibilities.','Diuresed heart failure can sometimes be misclassified.'],[['Protein ratio','3.6 / 6.0 = 0.60'],['Threshold','Greater than 0.5'],['Meaning','Exudative criterion, not an etiology']],[PL])
q('Which additional finding meets Light criteria for an exudate?', 'Pleural LDH greater than two-thirds of the upper limit of normal serum LDH',[
 ('Pleural glucose below serum glucose by any amount','Glucose is useful etiologically but is not a Light criterion.'),('Serum albumin below 3.5 g/dL','This is not one of the criteria.'),('A unilateral distribution alone','Laterality does not define biochemical classification.')],
 'Keep the classification rule separate from ancillary clues', '**Light criteria use protein ratio, LDH ratio and pleural LDH relative to the serum upper limit.**',['The LDH ratio threshold is greater than 0.6.','One positive criterion is sufficient.'], '**Use glucose, pH and cells for the next diagnostic question.**',['A very low glucose can occur in infection, rheumatoid disease and malignancy.','Do not confuse a supportive etiological clue with the classification rule.'],[['Protein ratio','Greater than 0.5'],['LDH ratio','Greater than 0.6'],['Pleural LDH','Greater than two-thirds serum upper limit']],[PL])
q('A diuresed heart-failure patient has a marginally exudative effusion by Light criteria. Serum albumin is 3.8 and pleural albumin 2.3 g/dL. Which interpretation is most useful?', 'The serum–pleural albumin gradient of 1.5 g/dL supports a possible cardiac pseudoexudate in the clinical context',[
 ('The gradient proves pleural malignancy','It does not identify malignancy.'),('Diuretic treatment can never alter fluid classification','Concentration during diuresis can create a pseudoexudate.'),('The albumin gradient eliminates the need to investigate atypical features','Unilateral, febrile or nonresponding effusions still need assessment.')],
 'Consider pseudoexudates without dismissing concerning features', '**A gradient greater than about 1.2 g/dL can support a transudative mechanism after diuresis.**',['It is an adjunct when the clinical picture suggests heart failure.','Serum NT-proBNP can also support a cardiac contribution.'], '**Reconcile the chemistry with the whole presentation.**',['Multiple processes may coexist.','Do not use one gradient to exclude infection or malignancy when suspicion remains.'],[['Calculation','3.8 − 2.3 = 1.5 g/dL'],['Interpretation','Possible diuretic-associated pseudoexudate'],['Limit','Not independent proof of etiology']],[PL],style='clinical_scenario')
q('A patient with pneumonia has nonpurulent pleural fluid, pH 7.10 and a safely accessible collection on ultrasound. Which management is most appropriate?', 'Antibiotics plus intercostal drainage for a high-risk complicated parapneumonic effusion',[
 ('Antibiotics alone regardless of the low pH','This biochemical profile indicates a high risk of pleural infection needing drainage.'),('Observation until frank pus develops','Pus is not required before drainage is indicated.'),('Talc pleurodesis as initial infection treatment','Pleurodesis is not the initial source-control strategy for this infection.')],
 'Low pleural pH can identify infection requiring source control', '**BTS uses pH at most 7.2 as a high-risk threshold in the appropriate parapneumonic context.**',['Confirm a safely drainable collection.','Frank pus independently establishes a drainage indication.'], '**Combine source control with appropriate antimicrobial treatment.**',['Ultrasound guides placement and identifies loculations.','Reassess residual fluid and the clinical response.'],[['pH at most 7.2','High risk'],['Drainable collection','Insert a drain when appropriate'],['Treatment','Antibiotics and source control']],[PL],style='clinical_scenario')
q('A febrile patient with a parapneumonic effusion has pleural pH 7.30, LDH 1,300 IU/L, low glucose and ultrasound septations. What is the best approach?', 'Consider drainage because intermediate pH plus high LDH and other infection features increases concern',[
 ('Exclude complicated infection because pH is above 7.2','The intermediate pH range requires additional assessment.'),('Wait for pH to fall below 6.0 before acting','That is not the guideline threshold.'),('Diagnose a transudate from the pH alone','pH does not define Light classification.')],
 'The pH interval between 7.2 and 7.4 is not automatically reassuring', '**Assess LDH and other clinical or imaging evidence.**',['LDH above 900 IU/L supports concern in this interval.','Low glucose, a large collection and septations strengthen a drainage decision.'], '**Use a safely accessible site and monitor response.**',['Persistent sepsis needs reassessment.','The numerical result must be interpreted in the infectious context.'],[['pH 7.30','Intermediate risk'],['LDH 1,300 and septations','Additional concern'],['Decision','Consider drainage with clinical assessment']],[PL],style='clinical_scenario')
q('Which sampling problem can spuriously lower measured pleural fluid pH?', 'Contamination with local anesthetic',[
 ('Exposure to air as the expected acidifying artifact','Air exposure tends to raise pH.'),('A correctly handled anaerobic blood-gas syringe without contaminant','That is part of appropriate sampling.'),('Immediate blood-gas analysis','Prompt analysis reduces handling-related error.')],
 'A pH value is only as reliable as the specimen', '**Avoid local anesthetic contamination.**',['Use an appropriate blood-gas syringe and expel air.','Do not leave excess liquid heparin or introduce other fluid.'], '**Analyze promptly using the proper equipment.**',['pH paper is insufficiently accurate for this decision.','A discordant value should prompt review of technique and the clinical picture.'],[['Local anesthetic','Can lower pH'],['Air exposure','Can raise pH'],['Method','Prompt blood-gas measurement']],[PL,PR])
q('Frank pus is aspirated from the pleural space. What is the correct interpretation?', 'Empyema requiring antibiotics and drainage assessment without waiting for a pH result',[
 ('A transudate until Light criteria are calculated','Pus establishes pleural infection.'),('A finding that should be managed with diuresis alone','This does not provide infection source control.'),('An indication to wait for a positive culture before treatment','Cultures can be negative and waiting is inappropriate.')],
 'Macroscopic pus establishes a pleural infection syndrome', '**Do not delay source control for additional biochemical classification.**',['Send appropriate microbiology, including suitable culture containers.','Antibiotic selection reflects community or hospital acquisition and likely organisms.'], '**Monitor for incomplete drainage.**',['A small-bore drain is usually an appropriate initial approach.','Persistent collections may need intrapleural therapy or surgical review.'],[['Pus','Empyema'],['Initial treatment','Antibiotics plus drainage'],['Nonresponse','Reassess source control']],[PL],style='clinical_scenario')
q('Pleural infection remains loculated with a residual collection after initial tube drainage. Which intrapleural regimen has randomized-trial support?', 'Combined tissue plasminogen activator and DNase',[
 ('DNase alone as equally established therapy','The MIST2 benefit was from the combination, not DNase alone.'),('tPA alone as an equivalent proven substitute','Single-agent fibrinolytic therapy is not the established combined strategy.'),('Intrapleural talc instead of infection treatment','Talc is a pleurodesis agent, not this infection regimen.')],
 'Combined therapy addresses fibrin barriers and viscous material', '**tPA plus DNase can improve drainage in selected pleural infection.**',['Consider it when tube drainage has ceased but a residual collection remains.','Bleeding risk and contraindications require assessment.'], '**Use it within an ongoing source-control plan.**',['Confirm drain position and patency.','Persistent sepsis or treatment failure may require surgery rather than repeated delay.'],[['tPA','Fibrinolytic component'],['DNase','Reduces DNA-associated viscosity'],['Combined use','Evidence-supported selected strategy']],[MI,PL],style='clinical_scenario')
q('Which initial drain strategy is generally appropriate for established pleural infection under BTS guidance?', 'An image-guided small-bore chest tube, usually 14 F or smaller',[
 ('A mandatory large-bore tube in every case','Routine large-bore drainage is not required for all pleural infections.'),('Blind repeated needle punctures as definitive management of every loculation','Targeted source control and reassessment are preferable.'),('No drain if the patient is already receiving antibiotics','Antibiotics do not reliably sterilize an undrained infected collection.')],
 'Adequate positioning and maintenance matter more than assuming a larger tube is always better', '**Small-bore drainage is a usual initial strategy.**',['Use imaging to target the collection.','Maintain patency according to local protocols.'], '**Reassess the response rather than judging success by tube insertion alone.**',['Residual locules may remain.','Intrapleural therapy or surgical assessment can be necessary.'],[['Initial approach','Small-bore image-guided drainage'],['Monitoring','Patency, output and residual collection'],['Escalation','Based on ongoing infection and anatomy']],[PL])
q('A lymphocyte-predominant exudative effusion is found. Which interpretation is most appropriate?', 'Tuberculosis and malignancy are important possibilities, but the cell pattern alone is not diagnostic',[
 ('Lymphocytes prove tuberculous pleuritis','The finding is not specific.'),('Lymphocytes exclude malignancy','Malignant effusions can be lymphocyte-predominant.'),('The pattern establishes a cardiac transudate','Cell predominance does not overturn exudate classification.')],
 'Use differential cell counts to refine rather than close the differential', '**Chronic pleural processes often produce lymphocytic fluid.**',['TB prevalence, exposure and cancer risk change probability.','Chylous and other inflammatory effusions can also be lymphocytic.'], '**Select confirmatory tests from the clinical context.**',['Cytology, pleural tissue and mycobacterial investigations may be needed.','Do not start a major treatment solely on cell predominance.'],[['Lymphocytic exudate','Broad chronic-process differential'],['TB / malignancy','Important competing causes'],['Confirmation','Microbiology, cytology or tissue as appropriate']],[PL])
q('In a high-TB-prevalence setting, what is the appropriate role of elevated pleural fluid adenosine deaminase in a compatible lymphocytic exudate?', 'It supports tuberculous pleuritis but requires contextual interpretation and does not supply drug susceptibility information',[
 ('It proves rifampicin susceptibility','ADA is not a resistance assay.'),('It excludes lymphoma and all other causes','Other disorders can elevate ADA.'),('It makes all microbiological investigation unnecessary in every patient','Organism detection and susceptibility can remain important.')],
 'ADA is an adjunct whose predictive value depends on context', '**A compatible phenotype and local prevalence affect its usefulness.**',['A low-probability setting changes the meaning of a positive result.','Other infections and inflammatory or malignant conditions can confound it.'], '**Seek organism or tissue evidence when indicated.**',['Pleural biopsy can provide histology and microbiology.','Consider respiratory samples even when pleural disease dominates.'],[['ADA','Supportive biochemical evidence'],['Limit','Not species or resistance confirmation'],['Context','Prevalence and competing diagnoses']],[PL])
q('Pleural fluid has markedly elevated amylase. Which differential should be considered?', 'Pancreatic disease, esophageal rupture and selected malignant effusions',[
 ('Heart failure as the only possible cause','It does not explain the principal amylase-rich differential.'),('Chylothorax established by amylase','Chylous diagnosis relies on lipid/chylomicron evidence.'),('A normal pleural process requiring no clinical correlation','A marked abnormality warrants etiological assessment.')],
 'An unusual biochemical marker can identify a nonpulmonary source', '**Amylase-rich fluid is not synonymous with pancreatitis.**',['Esophageal leakage can be rapidly life-threatening.','Isoenzyme and imaging information may help distinguish sources.'], '**Use symptoms and urgency to direct imaging and intervention.**',['Severe pain or systemic deterioration after vomiting requires urgent assessment.','Pancreatic fistula may produce a large recurrent effusion.'],[['Pancreatic source','Pancreatitis or fistula'],['Esophageal source','Leak or rupture'],['Other','Selected malignancies']],[PL])
q('Milky pleural fluid contains chylomicrons. Which diagnosis is established?', 'Chylothorax',[
 ('Pseudochylothorax','This is cholesterol-rich fluid associated with chronic pleural disease rather than chylomicron-defined chyle.'),('Empyema solely because the fluid is opaque','Pus can look cloudy, but chylomicrons identify chyle.'),('Hemothorax','That requires a blood-rich fluid with appropriate hematocrit findings.')],
 'Appearance suggests a category but lipid evidence defines it', '**Chylomicrons establish a chylous effusion.**',['Thoracic duct injury and malignancy are important causes.','A triglyceride concentration above about 110 mg/dL is supportive; intermediate values require clarification.'], '**Assess the underlying cause and nutritional impact.**',['Persistent loss affects calories, lymphocytes and proteins.','Treatment can include dietary, drainage and definitive duct-directed strategies.'],[['Chylothorax','Chylomicrons'],['Pseudochylothorax','Cholesterol-rich chronic effusion'],['Cloudy appearance','Not specific by itself']],[PL])
q('A bloody pleural aspirate has hematocrit 24% while peripheral blood hematocrit is 40%. Which interpretation is most appropriate?', 'Hemothorax, because the pleural-to-blood hematocrit ratio is 60%',[
 ('A nonhemorrhagic effusion because the pleural hematocrit is below 40%','The relevant comparison is with peripheral blood.'),('A transudate based on appearance','Blood-rich fluid needs specific evaluation.'),('Malignant effusion proven solely by the red color','Malignancy is one possible cause, not established by appearance.')],
 'Use the hematocrit ratio rather than color alone', '**A pleural hematocrit at least half the peripheral value supports hemothorax.**',['Dilution over time can yield lower ratios in a true hemorrhagic collection.','Trauma, procedures and vascular causes must be considered.'], '**Assess circulatory stability and ongoing bleeding.**',['Drainage and surgical or interventional evaluation depend on severity.','Do not treat a substantial hemothorax as a routine diagnostic effusion.'],[['Calculation','24 / 40 = 0.60'],['Threshold','At least 0.50 supports hemothorax'],['Priority','Bleeding severity and source']],[PR],style='clinical_scenario')
q('Before a nonemergency pleural fluid aspiration, which practice improves procedural safety?', 'Thoracic ultrasound assessment at the procedure site with the patient in the intended position',[
 ('Choosing a site from an old radiograph alone','Fluid and diaphragm position may differ from the earlier image.'),('Puncturing below the rib to avoid the intercostal bundle','The main neurovascular bundle runs along the inferior rib margin.'),('Using the same landmark site for every patient','Anatomy, fluid location and adjacent structures vary.')],
 'Image the anatomy that will actually be sampled', '**Ultrasound helps identify fluid and avoid diaphragm, lung and abdominal organs.**',['Training and correct interpretation are essential.','Marking should correspond to the procedure position and timing.'], '**Use a complete procedural safety process.**',['Review indication, consent, bleeding risks and equipment.','Enter using an appropriate safe approach relative to the rib and imaged anatomy.'],[['Ultrasound','Fluid and adjacent structures'],['Position','Same as intended procedure'],['Safety','Anatomy, preparation and technique']],[PR])
q('During therapeutic pleural aspiration, the patient develops chest tightness and persistent cough after 800 mL has drained. What is the best action?', 'Stop drainage and reassess, rather than continuing to a predetermined maximum volume',[
 ('Continue rapidly until 2 litres are removed','Symptoms are a reason to stop even before a numerical limit.'),('Apply strong wall suction to finish sooner','Rapid negative-pressure drainage can increase complications.'),('Ignore symptoms if oxygen saturation has not yet fallen','Symptoms can precede major deterioration.')],
 'Patient symptoms override a planned drainage target', '**Chest pain, tightness, persistent cough or worsening breathlessness warrants stopping.**',['Non-expandable lung or re-expansion injury may be relevant.','BTS generally advises slow drainage and no more than 1.5 L in one attempt without expert oversight.'], '**Reassess oxygenation and the pleural space.**',['Avoid vacuum bottles or wall suction for routine therapeutic aspiration.','Investigate new clinical deterioration promptly.'],[['Symptoms','Stop and reassess'],['Technique','Slow controlled drainage'],['Volume','A general ceiling is not a target to reach']],[PR],style='clinical_scenario')
